export type CustomerVerificationMode = "none" | "government_id" | "government_id_firearm_credential";
export type FirearmCredentialType = "none" | "foid" | "ltc" | "fpic";

export type CustomerVerificationRequirement = {
  mode: CustomerVerificationMode;
  min_age: number;
  credential_required: FirearmCredentialType;
  credential_state: string;
};

export type IdentityVerificationPolicyConfig = {
  matching_rule_ids: number[];
  applicable_states: string[];
  mode: Exclude<CustomerVerificationMode, "none">;
  min_age: number;
  required_credential: FirearmCredentialType;
};

export type IdentityVerificationPolicyRule = {
  id: number;
  name: string;
  type: string;
  identity_verification_config: IdentityVerificationPolicyConfig | null;
};

export type MatchedIdentityClassification = {
  productIds: Set<number>;
  lineItemIds: Set<string>;
};

export type IdentityVerificationRequirement = {
  requirementId: string;
  ruleId: number;
  ruleName: string;
  productIds: number[];
  lineItemIds: string[];
  customerVerification: CustomerVerificationRequirement;
};

export type IdentityVerificationApprovalRecord = {
  requirementId: string;
  data?: {
    internal_status?: string | null;
    verification_approved?: boolean;
  };
};

const STATE_NAME_TO_CODE: Record<string, string> = {
  ILLINOIS: "IL",
  MASSACHUSETTS: "MA",
  "NEW JERSEY": "NJ",
};

const CREDENTIAL_BY_STATE: Record<string, Exclude<FirearmCredentialType, "none">> = {
  IL: "foid",
  MA: "ltc",
  NJ: "fpic",
};

const STATE_BY_CREDENTIAL: Record<Exclude<FirearmCredentialType, "none">, string> = {
  foid: "IL",
  ltc: "MA",
  fpic: "NJ",
};

export const normalizeCredentialState = (value?: string | null) => {
  const normalized = String(value || "").trim().toUpperCase();

  return STATE_NAME_TO_CODE[normalized] || normalized;
};

export const getSupportedCredentialForState = (state?: string | null) => {
  const stateCode = normalizeCredentialState(state);

  return CREDENTIAL_BY_STATE[stateCode] || null;
};

export const isIdentityVerificationApprovalRecordApproved = (
  record?: IdentityVerificationApprovalRecord | null
) =>
  record?.data?.verification_approved === true ||
  String(record?.data?.internal_status || "").toLowerCase() === "approved";

export const hasPendingIdentityVerification = (
  required: boolean,
  requirements: Array<Pick<IdentityVerificationRequirement, "requirementId">> | null | undefined,
  records: IdentityVerificationApprovalRecord[] | null | undefined
) => {
  if (!required) return false;
  if (!Array.isArray(requirements) || requirements.length === 0) return true;

  const recordsByRequirementId = new Map(
    (Array.isArray(records) ? records : []).map((record) => [record.requirementId, record])
  );

  return requirements.some(
    (requirement) =>
      !isIdentityVerificationApprovalRecordApproved(
        recordsByRequirementId.get(requirement.requirementId)
      )
  );
};

export const isIdentityVerificationFeatureEnabled = (value: unknown) => value === true;

export const normalizeIdentityVerificationPolicyConfig = (
  value: unknown
): IdentityVerificationPolicyConfig | null => {
  if (!value || typeof value !== "object") return null;

  const config = value as Record<string, unknown>;
  const mode =
    config.mode === "government_id_firearm_credential"
      ? ("government_id_firearm_credential" as const)
      : config.mode === "government_id"
        ? ("government_id" as const)
        : null;

  if (!mode) return null;

  const matchingRuleIds = Array.from(
    new Set(
      (Array.isArray(config.matching_rule_ids) ? config.matching_rule_ids : [])
        .map(Number)
        .filter((id) => Number.isInteger(id) && id > 0)
    )
  );
  const requiredCredential =
    config.required_credential === "foid" ||
    config.required_credential === "ltc" ||
    config.required_credential === "fpic"
      ? config.required_credential
      : ("none" as const);
  const hasExplicitStateScope = Array.isArray(config.applicable_states);
  const rawApplicableStates: unknown[] = hasExplicitStateScope
    ? config.applicable_states as unknown[]
    : [];
  const applicableStates = Array.from(
    new Set(
      rawApplicableStates
        .map((state) => normalizeCredentialState(String(state || "")))
        .filter(Boolean)
    )
  );
  const rawMinAge = Number(config.min_age || 0);

  if (!matchingRuleIds.length) return null;

  if (
    mode === "government_id_firearm_credential" &&
    !hasExplicitStateScope &&
    requiredCredential !== "none"
  ) {
    applicableStates.push(STATE_BY_CREDENTIAL[requiredCredential]);
  }

  if (mode === "government_id_firearm_credential" && !applicableStates.length) return null;

  return {
    matching_rule_ids: matchingRuleIds,
    applicable_states: applicableStates,
    mode,
    min_age: Number.isFinite(rawMinAge) ? Math.max(0, Math.floor(rawMinAge)) : 0,
    required_credential:
      mode === "government_id" || applicableStates.length !== 1
        ? "none"
        : getSupportedCredentialForState(applicableStates[0]) || requiredCredential,
  };
};

export const buildCustomerVerificationRequirement = ({
  mode,
  minAge,
  credentialRequired,
  state,
}: {
  mode: CustomerVerificationMode;
  minAge?: number | null;
  credentialRequired?: FirearmCredentialType | null;
  state?: string | null;
}): CustomerVerificationRequirement | null => {
  if (mode === "none") return null;

  if (mode === "government_id") {
    return {
      mode,
      min_age: Math.max(0, Number(minAge || 0)),
      credential_required: "none",
      credential_state: "none",
    };
  }

  const credentialState = normalizeCredentialState(state);
  const supportedCredential = getSupportedCredentialForState(credentialState);
  const credential = credentialRequired || "none";

  if (!supportedCredential || credential !== supportedCredential) {
    return null;
  }

  return {
    mode,
    min_age: Math.max(0, Number(minAge || 0)),
    credential_required: credential,
    credential_state: credentialState,
  };
};

export const resolveIdentityVerificationRequirements = (
  rules: IdentityVerificationPolicyRule[],
  matchedClassifications: Map<number, MatchedIdentityClassification>,
  destinationState?: string | null,
  identityVerificationEnabled = true
): IdentityVerificationRequirement[] => {
  if (!identityVerificationEnabled) return [];

  return rules
    .filter((rule) => rule.type === "identity_verification" && rule.identity_verification_config)
    .flatMap((policy) => {
      const config = policy.identity_verification_config;

      if (!config) return [];

      const destinationStateCode = normalizeCredentialState(destinationState);

      if (
        config.applicable_states.length > 0 &&
        (!destinationStateCode || !config.applicable_states.includes(destinationStateCode))
      ) {
        return [];
      }

      const matchedRules = config.matching_rule_ids
        .map((ruleId) => matchedClassifications.get(ruleId))
        .filter((match): match is MatchedIdentityClassification => Boolean(match));

      if (!matchedRules.length) return [];

      const credentialRequired =
        config.mode === "government_id_firearm_credential"
          ? getSupportedCredentialForState(destinationStateCode)
          : "none";

      const resolvedCustomerVerification = buildCustomerVerificationRequirement({
        mode: config.mode,
        minAge: config.min_age,
        credentialRequired,
        state: destinationStateCode,
      });

      if (!resolvedCustomerVerification) {
        console.error("[MasterFFL][IDV] invalid identity verification policy", {
          policyId: policy.id,
          policyName: policy.name,
          mode: config.mode,
          applicableStates: config.applicable_states,
          credentialRequired,
          destinationState: destinationState || null,
        });

        return [];
      }

      const customerVerification: CustomerVerificationRequirement = {
        ...resolvedCustomerVerification,
        credential_state:
          config.mode === "government_id" && config.applicable_states.length > 0
            ? destinationStateCode
            : resolvedCustomerVerification.credential_state,
      };

      const productIds = Array.from(
        new Set(matchedRules.flatMap((match) => Array.from(match.productIds)))
      );
      const lineItemIds = Array.from(
        new Set(matchedRules.flatMap((match) => Array.from(match.lineItemIds)))
      );
      const requirementId = [
        "rule",
        policy.id,
        "identity-verification",
        customerVerification.mode,
        customerVerification.min_age,
        customerVerification.credential_required,
        customerVerification.credential_state,
      ].join(":");

      return [{
        requirementId,
        ruleId: policy.id,
        ruleName: policy.name,
        productIds,
        lineItemIds,
        customerVerification,
      }];
    });
};
