import { useMasterFFL } from "../index"; // same file exports useMasterFFL in your current setup
import MasterFFLForm from "./MasterFFLForm";
import MasterFFLNonRegulatedPickup from "./MasterFFLNonRegulatedPickup";

const DECLARED_NON_US_FIELD_VALUE = "true";
const DECLARED_NON_US_FIELD_DEFAULT_VALUE = "false";
const MASTERFFL_LOGO_URL = "https://api-qa.masterffl.com/ffl/bigcommerce/app/v4/images/masterffl.svg";
const IDENTITY_VERIFICATION_POLL_INTERVAL_MS = 1500;
const IDENTITY_VERIFICATION_POLL_ATTEMPTS = 20;

const getConfiguredButtonRadius = (value: unknown) => {
  const radius = Number(value);

  return Number.isFinite(radius) ? Math.max(0, Math.min(40, radius)) : 20;
};

type IdentityVerificationSessionRecord = {
  requirementId: string;
  ruleId: number;
  status: boolean;
  data?: {
    url?: string | null;
    requirement_id?: string;
    storehash?: string;
    checkout_id?: string | null;
    orderid?: string | null;
    vendor_data?: string;
    didit_session_id?: string | null;
    didit_session_number?: number | null;
    didit_status?: string | null;
    internal_status?: string | null;
    verification_required?: boolean;
    verification_approved?: boolean;
    artifact_transfer_status?: string | null;
    artifact_transfer_attempts?: number | null;
    artifact_transferred_at?: string | null;
  };
  error?: string;
};

const getIdentityVerificationRecords = (): IdentityVerificationSessionRecord[] => {
  if (typeof window === "undefined") return [];

  return Array.isArray((window as any).masterFFLIdentityVerifications)
    ? [...(window as any).masterFFLIdentityVerifications]
    : [];
};

const isIdentityVerificationApproved = (record: IdentityVerificationSessionRecord) =>
  record.data?.verification_approved === true ||
  String(record.data?.internal_status || "").toLowerCase() === "approved";

const isIdentityVerificationDeclined = (record: IdentityVerificationSessionRecord) =>
  String(record.data?.internal_status || record.data?.didit_status || "").toLowerCase() === "declined";

const wait = (duration: number) =>
  new Promise<void>((resolve) => window.setTimeout(resolve, duration));

