import { useCallback, useMemo, useRef, useState } from "react";
import { SDK } from "../../../sdk";
import type { MasterFFLContextType } from "../../../types";
import { useMasterFFL } from "../index";

type PickupMode = "delivery" | "pickup";
type BopisPickupLocation = MasterFFLContextType["bopisSettings"]["pickupLocations"][number];

const BOPIS_CHECKOUT_INCLUDE = {
  "consignments.availableShippingOptions": true,
  "consignments.lineItems.physicalItems": true,
} as any;

const normalizePickupText = (value: unknown): string =>
  String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

const findBopisShippingOption = (consignment: any) => {
  const options = consignment?.availableShippingOptions || [];

  if (!Array.isArray(options)) return null;

  return (
    options.find((option: any) => {
      const optionText = normalizePickupText(
        [
          option?.description,
          option?.type,
          option?.id,
          option?.module,
          option?.method,
          option?.displayName,
        ].filter(Boolean).join(" ")
      );

      return (
        optionText.includes("pickup") ||
        optionText.includes("pick up") ||
        optionText.includes("in store") ||
        optionText.includes("instore")
      );
    }) || null
  );
};

const findBopisConsignment = (consignments: any[], lineItems: any[]) => {
  const expectedLineItemIds = new Set(lineItems.map((item: any) => String(item.itemId)));

  return (
    consignments.find((consignment: any) => {
      const consignmentLineItemIds = [
        ...(Array.isArray(consignment?.lineItemIds) ? consignment.lineItemIds : []),
        ...(Array.isArray(consignment?.lineItems?.physicalItems)
          ? consignment.lineItems.physicalItems.map((item: any) => item.id ?? item.itemId)
          : []),
      ].map((itemId: any) => String(itemId));

      if (consignmentLineItemIds.length === 0) {
        return false;
      }

      return consignmentLineItemIds.every((itemId: string) => expectedLineItemIds.has(itemId));
    }) || consignments[0] || null
  );
};

function setFormControlValue(element: HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement, value: string) {
  const tagName = element.tagName;

  if (tagName === "INPUT") {
    const input = element as HTMLInputElement;
    if (input.type === "checkbox" || input.type === "radio") {
      const checkedSetter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "checked")?.set;
      const boolValue = value === "true" || value === "on" || value === "1";
      checkedSetter ? checkedSetter.call(input, boolValue) : (input.checked = boolValue);
    } else {
      const valueSetter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")?.set;
      valueSetter ? valueSetter.call(input, value) : (input.value = value);
    }
  } else if (tagName === "TEXTAREA") {
    const textarea = element as HTMLTextAreaElement;
    const valueSetter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value")?.set;
    valueSetter ? valueSetter.call(textarea, value) : (textarea.value = value);
  } else if (tagName === "SELECT") {
    const select = element as HTMLSelectElement;
    const valueSetter = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, "value")?.set;
    valueSetter ? valueSetter.call(select, value) : (select.value = value);
  }

  element.dispatchEvent(new Event("input", { bubbles: true }));
  element.dispatchEvent(new Event("change", { bubbles: true }));
}

function syncShippingAddressForm(address: Record<string, unknown>) {
  Object.keys(address).forEach((key) => {
    const input = document.querySelector(`[name="shippingAddress.${key}"]`) as
      | HTMLInputElement
      | HTMLTextAreaElement
      | HTMLSelectElement
      | null;
    const addressLine1Input =
      key === "address1" ? (document.getElementById("addressLine1Input") as HTMLInputElement | null) : null;
    const nextValue = String(address[key] ?? "");

    if (input) {
      setFormControlValue(input, nextValue);
    }

    if (addressLine1Input) {
      setFormControlValue(addressLine1Input, nextValue);
    }
  });
}

function clearShippingAddressForm() {
  [
    "firstName",
    "lastName",
    "company",
    "phone",
    "address1",
    "address2",
    "city",
    "stateOrProvinceCode",
    "stateOrProvince",
    "postalCode",
    "country",
    "countryCode",
  ].forEach((key) => {
    const input = document.querySelector(`[name="shippingAddress.${key}"]`) as
      | HTMLInputElement
      | HTMLTextAreaElement
      | HTMLSelectElement
      | null;
    const addressLine1Input =
      key === "address1" ? (document.getElementById("addressLine1Input") as HTMLInputElement | null) : null;

    if (input) {
      setFormControlValue(input, "");
    }

    if (addressLine1Input) {
      setFormControlValue(addressLine1Input, "");
    }
  });
}

function clearShippingAddressFormAfterRender() {
  clearShippingAddressForm();

  if (typeof window === "undefined") return;

  window.requestAnimationFrame(() => clearShippingAddressForm());
  window.setTimeout(() => clearShippingAddressForm(), 0);
  window.setTimeout(() => clearShippingAddressForm(), 150);
}

function isPickupOptionText(text: string) {
  const normalizedText = normalizePickupText(text);

  return (
    normalizedText.includes("pickup") ||
    normalizedText.includes("pick up") ||
    normalizedText.includes("in store") ||
    normalizedText.includes("instore")
  );
}

function filterBopisShippingOptionsDom(mode: "bopis" | "reset") {
  const optionRows = Array.from(document.querySelectorAll<HTMLElement>(".shippingOptions-container .form-checklist-item"));

  optionRows.forEach((row) => {
    if (mode === "reset") {
      row.style.display = "";
      row.removeAttribute("data-masterffl-hidden-option");
      return;
    }

    const shouldHideOption = !isPickupOptionText(row.textContent || "");

    row.style.display = shouldHideOption ? "none" : "";

    if (shouldHideOption) {
      row.setAttribute("data-masterffl-hidden-option", "true");
    } else {
      row.removeAttribute("data-masterffl-hidden-option");
    }
  });
}

function selectBopisShippingOptionDom(shippingOptionId: string) {
  const escapedOptionId =
    typeof CSS !== "undefined" && typeof CSS.escape === "function"
      ? CSS.escape(shippingOptionId)
      : shippingOptionId.replace(/["\\]/g, "\\$&");
  const input = document.querySelector<HTMLInputElement>(
    `input[type="radio"][value="${escapedOptionId}"]`
  );

  if (!input) return false;

  if (!input.checked) {
    input.click();
  }

  setFormControlValue(input, "true");

  return true;
}

async function waitForBopisShippingOptionDom(shippingOptionId: string) {
  for (let attempt = 0; attempt < 10; attempt += 1) {
    if (selectBopisShippingOptionDom(shippingOptionId)) {
      return true;
    }

    await new Promise((resolve) => window.setTimeout(resolve, 250));
  }

  return false;
}

function formatBopisPickupAddress(pickupLocation?: BopisPickupLocation | null) {
  const location = pickupLocation?.location;

  if (!location) return "";

  return [
    location.address1,
    location.address2,
    [location.city, location.stateOrProvinceCode || location.stateOrProvince, location.postalCode]
      .filter(Boolean)
      .join(", "),
    location.countryCode,
  ]
    .filter(Boolean)
    .join(" ");
}

function formatBopisPickupLocationInfoAddress(pickupLocation?: BopisPickupLocation | null) {
  const address = pickupLocation?.location_info?.address;

  if (!address) return "";

  return [
    address.address1,
    address.address2,
    [address.city, address.state, address.zip].filter(Boolean).join(", "),
    address.country_code,
  ]
    .filter(Boolean)
    .join(" ");
}

const BOPIS_OPERATING_HOUR_DAYS = [
  ["monday", "Mon"],
  ["tuesday", "Tue"],
  ["wednesday", "Wed"],
  ["thursday", "Thu"],
  ["friday", "Fri"],
  ["saturday", "Sat"],
  ["sunday", "Sun"],
] as const;

function formatBopisPickupTime(value?: string) {
  if (!value) return "";

  const [hourText, minuteText = "00"] = value.split(":");
  const hour = Number(hourText);
  const minute = Number(minuteText);

  if (!Number.isInteger(hour) || !Number.isInteger(minute)) {
    return value;
  }

  const period = hour >= 12 ? "PM" : "AM";
  const displayHour = hour % 12 || 12;

  return `${displayHour}:${String(minute).padStart(2, "0")} ${period}`;
}

function getBopisOperatingHours(pickupLocation?: BopisPickupLocation | null) {
  const operatingHours = pickupLocation?.location_info?.operating_hours;

  if (!operatingHours || typeof operatingHours !== "object") return [];

  return BOPIS_OPERATING_HOUR_DAYS.map(([key, label]) => {
    const day = operatingHours[key];
    const isOpen = !!day?.open;
    const opening = formatBopisPickupTime(day?.opening);
    const closing = formatBopisPickupTime(day?.closing);

    return {
      key,
      label,
      isOpen,
      hours: isOpen && opening && closing ? `${opening} - ${closing}` : "Closed",
    };
  });
}

function getGroupedBopisOperatingHours(hours: ReturnType<typeof getBopisOperatingHours>) {
  return hours.reduce<Array<{ label: string; hours: string; isOpen: boolean }>>((groups, day) => {
    const previous = groups[groups.length - 1];

    if (previous && previous.hours === day.hours && previous.isOpen === day.isOpen) {
      const [start] = previous.label.split(" - ");
      previous.label = `${start} - ${day.label}`;

      return groups;
    }

    groups.push({
      label: day.label,
      hours: day.hours,
      isOpen: day.isOpen,
    });

    return groups;
  }, []);
}

function hasUsableBopisPickupAddress(pickupLocation?: BopisPickupLocation | null) {
  const location = pickupLocation?.location;

  return !!(location?.address1 && location?.city && location?.postalCode);
}

