const getConfiguredButtonRadius = (value: unknown) => {
  const radius = Number(value);

  return Number.isFinite(radius) ? Math.max(0, Math.min(40, radius)) : 20;
};

const getModeButtonStyle = (isActive: boolean, buttonRadius: number) => ({
  flex: "1 1 0",
  minHeight: 46,
  minWidth: 0,
  borderRadius: buttonRadius,
  border: "1px solid #000000",
  cursor: "pointer",
  fontWeight: 700,
  letterSpacing: 0,
  lineHeight: 1.2,
  padding: "10px",
  whiteSpace: "normal" as const,
  ...(isActive
    ? {
        background: "#000000",
        borderColor: "#000000",
        color: "#ffffff",
      }
    : {
        background: "#ffffff",
        borderColor: "#000000",
        color: "#000000",
      }),
});

const MasterFFLNonRegulatedPickup = () => {
  const { bopisSettings, checkoutService, config, setShippingLocked } = useMasterFFL();
  const buttonRadius = getConfiguredButtonRadius((window as any).masterFFLConditional?.buttonRadius);
  const [mode, setMode] = useState<PickupMode>(() =>
    typeof window !== "undefined" &&
    !!config.checkoutId &&
    sessionStorage.getItem(`${config.checkoutId}-nonRegulatedPickupSelected`) === "true"
      ? "pickup"
      : "delivery"
  );
  const [selectedPickupMethodId, setSelectedPickupMethodId] = useState<number | null>(null);
  const [isApplyingPickup, setIsApplyingPickup] = useState(false);
  const [isPickupApplied, setIsPickupApplied] = useState(false);
  const [pickupError, setPickupError] = useState("");
  const applyPromiseRef = useRef<Promise<void> | null>(null);

  const pickupLocations = Array.isArray(bopisSettings.pickupLocations)
    ? bopisSettings.pickupLocations
    : [];

  const selectedPickupLocation = useMemo(() => {
    return (
      pickupLocations.find((location) => location.pickupMethodId === selectedPickupMethodId) ||
      pickupLocations.find((location) => location.pickupMethodId === bopisSettings.pickupMethodId) ||
      pickupLocations[0] ||
      null
    );
  }, [bopisSettings.pickupMethodId, pickupLocations, selectedPickupMethodId]);
  const selectedPickupOperatingHours = getBopisOperatingHours(selectedPickupLocation);
  const selectedPickupGroupedOperatingHours = getGroupedBopisOperatingHours(selectedPickupOperatingHours);

  const deleteAllConsignments = useCallback(async () => {
    if (!config.checkoutId) return;

    const selectors = await checkoutService.loadCheckout(config.checkoutId, {
      params: { include: { "consignments.availableShippingOptions": true } },
    });
    const consignments = selectors.data.getConsignments?.() || [];

    for (const consignment of consignments) {
      if (consignment?.id) {
        await checkoutService.deleteConsignment(consignment.id);
      }
    }
  }, [checkoutService, config.checkoutId]);

  const resetNativeShippingAddress = useCallback(async () => {
    clearShippingAddressFormAfterRender();

    try {
      await checkoutService.updateShippingAddress({} as any, {
        params: {
          include: {
            "consignments.availableShippingOptions": true,
          },
        },
      });
    } catch (error) {
      console.warn("[MasterFFL][NonRegulatedPickup] native shipping address reset failed", error);
    } finally {
      clearShippingAddressFormAfterRender();
    }
  }, [checkoutService]);

  const updateBopisFee = useCallback(
    async (action: "apply" | "remove") => {
      if (!config.storeHash || !config.checkoutId) return;

      const response = await fetch(`${config.appUrl}/api/internal/bopis/fee`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "ngrok-skip-browser-warning": "true",
        },
        body: JSON.stringify({
          storeHash: config.storeHash,
          checkoutId: config.checkoutId,
          action,
        }),
      });

      if (!response.ok) {
        const data = await response.json().catch(() => null);
        throw new Error(data?.message || `Failed to ${action} BOPIS fee`);
      }
    },
    [config.appUrl, config.checkoutId, config.storeHash]
  );

  const removePickupSelection = useCallback(async () => {
    try {
      await updateBopisFee("remove");
      await deleteAllConsignments();
      filterBopisShippingOptionsDom("reset");
      await resetNativeShippingAddress();
    } catch (error) {
      console.error("[MasterFFL][NonRegulatedPickup] cleanup failed", error);
    } finally {
      clearShippingAddressFormAfterRender();
      setIsPickupApplied(false);
      setPickupError("");
      if (config.checkoutId) {
        sessionStorage.removeItem(`${config.checkoutId}-nonRegulatedPickupSelected`);
      }
    }
  }, [config.checkoutId, deleteAllConsignments, resetNativeShippingAddress, updateBopisFee]);

  const applyPickup = useCallback(async (pickupMethodIdOverride?: number | null) => {
    if (applyPromiseRef.current) {
      return applyPromiseRef.current;
    }

    const applyPromise = (async () => {
      setIsApplyingPickup(true);
      setPickupError("");
      if (config.checkoutId) {
        sessionStorage.setItem(`${config.checkoutId}-nonRegulatedPickupSelected`, "true");
      }

      const activePickupLocation =
        pickupLocations.find((location) => location.pickupMethodId === pickupMethodIdOverride) ||
        selectedPickupLocation;

      if (!activePickupLocation) {
        throw new Error("No pickup location is available.");
      }

      await updateBopisFee("remove");

      const cart = await SDK.getCart();
      const physicalItems = cart?.lineItems?.physicalItems || [];
      const lineItems = physicalItems
        .map((item: any) => ({
          itemId: item.id ?? item.entityId,
          quantity: item.quantity,
        }))
        .filter((item: any) => item.itemId && item.quantity > 0);

      if (lineItems.length === 0) {
        throw new Error("No physical cart items are available for pickup.");
      }

      const activeLocationAddress = activePickupLocation.location;
      const hasActiveAddress = hasUsableBopisPickupAddress(activePickupLocation);
      const pickupShippingAddress = {
        firstName: "In-Store",
        lastName: "Pickup",
        phone: activeLocationAddress?.phone || "0000000000",
        company: activeLocationAddress?.name || activePickupLocation.displayName || bopisSettings.location || "In-Store Pickup",
        address1: hasActiveAddress ? activeLocationAddress?.address1 || "" : bopisSettings.location || "In-Store Pickup",
        address2: hasActiveAddress ? activeLocationAddress?.address2 || "" : "",
        city: hasActiveAddress ? activeLocationAddress?.city || "" : "Pickup",
        stateOrProvinceCode: hasActiveAddress
          ? activeLocationAddress?.stateOrProvinceCode || activeLocationAddress?.stateOrProvince || ""
          : "TX",
        stateOrProvince: hasActiveAddress
          ? activeLocationAddress?.stateOrProvince || activeLocationAddress?.stateOrProvinceCode || ""
          : "TX",
        postalCode: hasActiveAddress ? activeLocationAddress?.postalCode || "" : "75001",
        countryCode: activeLocationAddress?.countryCode || "US",
        country: activeLocationAddress?.countryCode === "US" || !activeLocationAddress?.countryCode
          ? "United States"
          : activeLocationAddress.countryCode,
        customFields: [],
      };

      syncShippingAddressForm(pickupShippingAddress);

      const updatedCheckoutSelectors = await checkoutService.updateShippingAddress(pickupShippingAddress, {
        params: {
          include: {
            "consignments.availableShippingOptions": true,
          },
        },
      });

      const checkoutSelectors = await checkoutService.loadCheckout(config.checkoutId, {
        params: { include: BOPIS_CHECKOUT_INCLUDE },
      });
      const consignments =
        checkoutSelectors.data.getConsignments?.() ||
        updatedCheckoutSelectors.data.getConsignments?.() ||
        [];
      const pickupConsignment = findBopisConsignment(consignments, lineItems);

      if (!pickupConsignment) {
        throw new Error("In-store pickup could not be assigned to this checkout.");
      }

      const pickupShippingOption = findBopisShippingOption(pickupConsignment);

      if (!pickupShippingOption?.id) {
        throw new Error("No in-store pickup shipping option is available for this checkout.");
      }

      filterBopisShippingOptionsDom("bopis");
      const didSelectPickupOption = await waitForBopisShippingOptionDom(pickupShippingOption.id);

      if (!didSelectPickupOption) {
        await checkoutService.selectConsignmentShippingOption(pickupConsignment.id, pickupShippingOption.id);
      }

      const finalCheckoutSelectors = await checkoutService.loadCheckout(config.checkoutId, {
        params: { include: BOPIS_CHECKOUT_INCLUDE },
      });
      syncShippingAddressForm(pickupShippingAddress);
      filterBopisShippingOptionsDom("bopis");

      const finalConsignments = finalCheckoutSelectors.data.getConsignments?.() || [];
      const finalPickupConsignment = findBopisConsignment(finalConsignments, lineItems);
      const finalPickupShippingOption = findBopisShippingOption(finalPickupConsignment);

      if (
        finalPickupConsignment?.id &&
        finalPickupShippingOption?.id &&
        finalPickupConsignment.selectedShippingOption?.id !== finalPickupShippingOption.id
      ) {
        const didSelectFinalPickupOption = await waitForBopisShippingOptionDom(finalPickupShippingOption.id);

        if (!didSelectFinalPickupOption) {
          await checkoutService.selectConsignmentShippingOption(finalPickupConsignment.id, finalPickupShippingOption.id);
        }
      }

      await checkoutService.loadCheckout(config.checkoutId, {
        params: { include: BOPIS_CHECKOUT_INCLUDE },
      });
      syncShippingAddressForm(pickupShippingAddress);
      filterBopisShippingOptionsDom("bopis");

      await updateBopisFee("apply");
      await checkoutService.loadCheckout(config.checkoutId, {
        params: { include: BOPIS_CHECKOUT_INCLUDE },
      });

      if (finalPickupShippingOption?.id) {
        window.setTimeout(() => {
          selectBopisShippingOptionDom(finalPickupShippingOption.id);
          filterBopisShippingOptionsDom("bopis");
        }, 0);
      }

      setIsPickupApplied(true);
      setShippingLocked(false);
      if (config.checkoutId) {
        sessionStorage.setItem(`${config.checkoutId}-nonRegulatedPickupSelected`, "true");
      }
    })();

    applyPromiseRef.current = applyPromise;

    try {
      await applyPromise;
    } catch (error: any) {
      console.error("[MasterFFL][NonRegulatedPickup] apply failed", error);
      setIsPickupApplied(false);
      setPickupError(error?.message || "Unable to apply pickup. Please try again.");
    } finally {
      applyPromiseRef.current = null;
      setIsApplyingPickup(false);
    }
  }, [
    bopisSettings.location,
    checkoutService,
    config.checkoutId,
    pickupLocations,
    selectedPickupLocation,
    setShippingLocked,
    updateBopisFee,
  ]);

  const handleModeChange = useCallback(async (nextMode: PickupMode) => {
    if (nextMode === mode) return;

    setMode(nextMode);

    if (nextMode === "delivery") {
      const hasStoredPickupSelection =
        !!config.checkoutId &&
        sessionStorage.getItem(`${config.checkoutId}-nonRegulatedPickupSelected`) === "true";

      if (isPickupApplied || hasStoredPickupSelection) {
        await removePickupSelection();
      } else {
        filterBopisShippingOptionsDom("reset");
        await resetNativeShippingAddress();
      }

      return;
    }

    await applyPickup(selectedPickupLocation?.pickupMethodId);
  }, [
    applyPickup,
    config.checkoutId,
    isPickupApplied,
    mode,
    removePickupSelection,
    resetNativeShippingAddress,
    selectedPickupLocation,
  ]);

  return (
    <div
      className="form-body"
      id="MasterFFL-non-regulated-pickup"
      style={{
        border: "1px solid #ebebeb",
        borderRadius: 4,
        marginBottom: 15,
        padding: "1.5rem",
      }}
    >
      <div style={{ display: "flex", flexWrap: "wrap", gap: 10, width: "100%" }}>
        <button
          className={mode === "delivery" ? "button--primary" : "button--secondary"}
          disabled={isApplyingPickup}
          onClick={() => void handleModeChange("delivery")}
          style={getModeButtonStyle(mode === "delivery", buttonRadius)}
          type="button"
        >
          DELIVERY
        </button>
        <button
          className={mode === "pickup" ? "button--primary" : "button--secondary"}
          disabled={isApplyingPickup}
          onClick={() => void handleModeChange("pickup")}
          style={getModeButtonStyle(mode === "pickup", buttonRadius)}
          type="button"
        >
          PICKUP
        </button>
      </div>

      {mode === "pickup" && (
        <div style={{ marginTop: 18 }}>
          <div style={{ color: "#111827", fontSize: 16, fontWeight: 700, marginBottom: 14 }}>
            Pickup Location
          </div>
          <div style={{ display: "grid", gap: 12 }}>
            {pickupLocations.map((pickupLocation) => {
              const inputId = `non-regulated-pickup-location-${pickupLocation.pickupMethodId}`;
              const address =
                formatBopisPickupLocationInfoAddress(pickupLocation) ||
                formatBopisPickupAddress(pickupLocation) ||
                pickupLocation.location?.name ||
                "Pickup location details unavailable";
              const isSelected = selectedPickupLocation?.pickupMethodId === pickupLocation.pickupMethodId;

              return (
                <label
                  className="form-label optimizedCheckout-form-label"
                  htmlFor={inputId}
                  key={pickupLocation.pickupMethodId}
                  style={{
                    alignItems: "center",
                    border: isSelected ? "2px solid #111827" : "1px solid #d8d8d8",
                    borderRadius: 4,
                    cursor: isApplyingPickup ? "default" : "pointer",
                    display: "grid",
                    gap: 16,
                    gridTemplateColumns: "28px 72px 1fr",
                    margin: 0,
                    minHeight: 94,
                    padding: "16px 18px",
                  }}
                >
                  <input
                    checked={isSelected}
                    disabled={isApplyingPickup}
                    id={inputId}
                    name="non-regulated-pickup-location"
                    onChange={() => {
                      setSelectedPickupMethodId(pickupLocation.pickupMethodId);
                      setIsPickupApplied(false);
                      void applyPickup(pickupLocation.pickupMethodId);
                    }}
                    style={{ height: 22, margin: 0, width: 22 }}
                    type="radio"
                  />
                  <div
                    aria-hidden="true"
                    style={{
                      alignItems: "center",
                      background: "#f3f4f6",
                      borderRadius: "50%",
                      color: "#111827",
                      display: "flex",
                      fontSize: 26,
                      fontWeight: 700,
                      height: 64,
                      justifyContent: "center",
                      lineHeight: 1,
                      width: 64,
                    }}
                  >
                    <BopisIcon name={isSelected ? "pin" : "store"} />
                  </div>
                  <div>
                    <div style={{ color: "#111827", fontSize: 16, fontWeight: 700 }}>
                      {pickupLocation.displayName || "Pickup Location"}
                    </div>
                    <div style={{ color: "#111827", marginTop: 5, whiteSpace: "pre-wrap" }}>
                      {address}
                    </div>
                  </div>
                </label>
              );
            })}
          </div>
          <div style={{ borderTop: "1px solid #e5e7eb", marginTop: 24, paddingTop: 22 }}>
            <div style={{ fontSize: 16, fontWeight: 700, letterSpacing: 0, marginBottom: 14 }}>
              2. PICKUP DETAILS
            </div>
            <div style={{ display: "grid", gap: 12 }}>
              <div
                style={{
                  alignItems: "center",
                  border: "1px solid #d8d8d8",
                  borderRadius: 4,
                  display: "grid",
                  gap: 24,
                  gridTemplateColumns: "72px 1fr",
                  padding: "18px 24px",
                }}
              >
                <div
                  aria-hidden="true"
                  style={{
                    alignItems: "center",
                    background: "#f3f4f6",
                    borderRadius: "50%",
                    color: "#111827",
                    display: "flex",
                    fontSize: 24,
                    fontWeight: 700,
                    height: 64,
                    justifyContent: "center",
                    width: 64,
                  }}
                >
                  <BopisIcon name="bag" />
                </div>
                <div style={{ borderLeft: "1px solid #e5e7eb", paddingLeft: 22 }}>
                  <div style={{ color: "#111827" }}>Pickup Method</div>
                  <div style={{ color: "#111827", fontWeight: 700, marginTop: 8 }}>
                    {isApplyingPickup
                      ? "Applying in-store pickup..."
                      : isPickupApplied
                        ? "In-Store Pickup"
                        : "In-store pickup will be selected automatically."}
                  </div>
                </div>
              </div>
              <div
                style={{
                  alignItems: "center",
                  border: "1px solid #d8d8d8",
                  borderRadius: 4,
                  display: "grid",
                  gap: 24,
                  gridTemplateColumns: "72px 1fr",
                  padding: "18px 24px",
                }}
              >
                <div
                  aria-hidden="true"
                  style={{
                    alignItems: "center",
                    background: "#f3f4f6",
                    borderRadius: "50%",
                    color: "#111827",
                    display: "flex",
                    fontSize: 24,
                    fontWeight: 700,
                    height: 64,
                    justifyContent: "center",
                    width: 64,
                  }}
                >
                  <BopisIcon name="note" />
                </div>
                <div style={{ borderLeft: "1px solid #e5e7eb", paddingLeft: 22 }}>
                  <div style={{ color: "#111827" }}>Pickup Instructions</div>
                  <div style={{ color: "#111827", fontWeight: 700, marginTop: 8, whiteSpace: "pre-wrap" }}>
                    {selectedPickupLocation?.collectionInstructions || bopisSettings.instructions || "None provided"}
                  </div>
                </div>
              </div>
              <div
                style={{
                  alignItems: "center",
                  border: "1px solid #d8d8d8",
                  borderRadius: 4,
                  display: "grid",
                  gap: 24,
                  gridTemplateColumns: "72px 1fr",
                  padding: "18px 24px",
                }}
              >
                <div
                  aria-hidden="true"
                  style={{
                    alignItems: "center",
                    background: "#f3f4f6",
                    borderRadius: "50%",
                    color: "#111827",
                    display: "flex",
                    fontSize: 24,
                    fontWeight: 700,
                    height: 64,
                    justifyContent: "center",
                    width: 64,
                  }}
                >
                  <BopisIcon name="clock" />
                </div>
                <div style={{ borderLeft: "1px solid #e5e7eb", paddingLeft: 22 }}>
                  <div style={{ color: "#111827" }}>Operating Hours</div>
                  <div style={{ marginTop: 8 }}>
                    {selectedPickupGroupedOperatingHours.length > 0 ? (
                      selectedPickupGroupedOperatingHours.map((day) => (
                        <div
                          key={`${day.label}-${day.hours}`}
                          style={{
                            color: day.isOpen ? "#111827" : "#6b7280",
                            display: "grid",
                            gap: 14,
                            gridTemplateColumns: "90px 1fr",
                            lineHeight: 1.45,
                          }}
                        >
                          <span>{day.label}</span>
                          <span style={{ fontWeight: day.isOpen ? 600 : 400 }}>{day.hours}</span>
                        </div>
                      ))
                    ) : (
                      <div style={{ color: "#6b7280" }}>Hours unavailable</div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
          {pickupError && (
            <ul className="form-field-errors" style={{ marginTop: 10 }}>
              <li className="form-field-error">
                <label aria-live="polite" className="form-inlineMessage" role="alert">
                  {pickupError}
                </label>
              </li>
            </ul>
          )}
        </div>
      )}

      {mode === "pickup" && (
        <style
          dangerouslySetInnerHTML={{
            __html: `
              #checkoutShippingAddress,
              #sameAsBilling,
              [data-test="shipping-mode-toggle"],
              #sameAsBilling + label {
                display: none;
              }
            `,
          }}
        />
      )}
    </div>
  );
};

export default MasterFFLNonRegulatedPickup;
