const normalizeText = (value: unknown) =>
  String(value ?? "").trim().toLowerCase();

const normalizeStateCode = (value: unknown) => {
  const normalized = String(value ?? "").trim().toUpperCase();
  return STATE_NAME_TO_CODE[normalized] || normalized;
};

const normalizeTypeLabel = (value: unknown) =>
  String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "-");

const REGION_CRITERION_TYPES = new Set<RuntimeRuleRegionCriterionType>([
  "federal",
  "state",
  "city_state",
  "county_state",
  "zip",
]);

const normalizeRegionText = (value: unknown) =>
  String(value ?? "").trim().replace(/\s+/g, " ").toUpperCase();

const normalizeZip = (value: unknown) => {
  const digits = String(value ?? "").replace(/\D/g, "");

  return digits.length >= 5 ? digits.slice(0, 5) : digits;
};

const splitRegionPair = (value: unknown) => {
  const raw = String(value ?? "").trim();
  const parts = raw.includes("|") ? raw.split("|") : raw.split(",");
  const state = normalizeStateCode(parts.pop() || "");
  const name = normalizeRegionText(parts.join(","));

  return name && state ? `${name}|${state}` : "";
};

const normalizeRegionCriterionValue = (
  type: RuntimeRuleRegionCriterionType,
  value: unknown
) => {
  if (type === "state") {
    return normalizeStateCode(value);
  }

  if (type === "city_state" || type === "county_state") {
    return splitRegionPair(value);
  }

  if (type === "zip") {
    return normalizeZip(value);
  }

  return String(value ?? "").trim();
};

const normalizeRuleRegionCriteria = (input: unknown): RuntimeRuleRegionCriterion[] => {
  let parsedInput = input;

  if (typeof input === "string") {
    try {
      parsedInput = JSON.parse(input);
    } catch {
      parsedInput = [];
    }
  }

  const criteria = Array.isArray(parsedInput) ? parsedInput : [];
  const seen = new Set<string>();
  const normalizedCriteria: RuntimeRuleRegionCriterion[] = [];

  criteria.forEach((criterion: any) => {
    const type = String(criterion?.type || "").trim().toLowerCase() as RuntimeRuleRegionCriterionType;
    const operator = criterion?.operator === "is_not" ? "is_not" : "is";

    if (!REGION_CRITERION_TYPES.has(type)) {
      return;
    }

    const values: string[] =
      type === "federal"
        ? []
        : Array.from(
            new Set(
              (Array.isArray(criterion?.values) ? criterion.values : [])
                .map((value: unknown) => normalizeRegionCriterionValue(type, value))
                .filter(Boolean)
            )
          ) as string[];

    const key = `${type}:${operator}:${values.join(";")}`;

    if (seen.has(key)) {
      return;
    }

    seen.add(key);
    normalizedCriteria.push({ type, operator, values });
  });

  return normalizedCriteria.some((criterion) => criterion.type === "federal")
    ? normalizedCriteria.filter((criterion) => criterion.type === "federal").slice(0, 1)
    : normalizedCriteria;
};

const getRuleRegionCriteria = (
  rule: Pick<RuntimeRule, "region_type" | "states" | "region_criteria">
) => {
  const advancedCriteria = normalizeRuleRegionCriteria(rule.region_criteria);

  if (advancedCriteria.length) {
    return advancedCriteria;
  }

  if (rule.region_type === "federal") {
    return [{ type: "federal", operator: "is", values: [] }] as RuntimeRuleRegionCriterion[];
  }

  const stateValues = (Array.isArray(rule.states) ? rule.states : [])
    .map((state) => normalizeRegionCriterionValue("state", state))
    .filter(Boolean);

  return stateValues.length
    ? [{ type: "state", operator: "is", values: Array.from(new Set(stateValues)) }] as RuntimeRuleRegionCriterion[]
    : [];
};

const getContextValuesForRegionType = (
  type: RuntimeRuleRegionCriterionType,
  context?: RuleRegionContext | null
) => {
  if (type === "federal") {
    return ["*"];
  }

  if (!context) {
    return [];
  }

  const state = normalizeStateCode(context.state || "");

  if (type === "state") {
    return state ? [state] : [];
  }

  if (type === "zip") {
    const zip = normalizeRegionCriterionValue("zip", context.zip);

    return zip ? [zip] : [];
  }

  if (type === "city_state") {
    const city = normalizeRegionText(context.city);

    return city && state ? [`${city}|${state}`] : [];
  }

  const counties = [
    context.county,
    ...(Array.isArray(context.counties) ? context.counties : []),
  ]
    .map((county) => normalizeRegionText(county))
    .filter(Boolean);

  return state ? Array.from(new Set(counties.map((county) => `${county}|${state}`))) : [];
};

const regionCriterionMatchesContext = (
  criterion: RuntimeRuleRegionCriterion,
  context?: RuleRegionContext | null
) => {
  if (criterion.type === "federal") {
    return true;
  }

  const contextValues = getContextValuesForRegionType(criterion.type, context);

  if (!contextValues.length) {
    return false;
  }

  const criterionValues = new Set(
    (criterion.values || [])
      .map((value) => normalizeRegionCriterionValue(criterion.type, value))
      .filter(Boolean)
  );

  return contextValues.some((value) => criterionValues.has(value));
};

const ruleAppliesToRegionContext = (
  rule: Pick<RuntimeRule, "region_type" | "states" | "region_criteria" | "region_match_mode">,
  context?: RuleRegionContext | null
) => {
  const criteria = getRuleRegionCriteria(rule);

  if (!criteria.length) {
    return false;
  }

  if (criteria.some((criterion) => criterion.type === "federal")) {
    return true;
  }

  if (!context) {
    return false;
  }

  const rowMatches = criteria.map((criterion) => {
    const matched = regionCriterionMatchesContext(criterion, context);

    return criterion.operator === "is_not" ? !matched : matched;
  });

  return rule.region_match_mode === "all"
    ? rowMatches.every(Boolean)
    : rowMatches.some(Boolean);
};

const getRuleRegionSpecificity = (
  rule: Pick<RuntimeRule, "region_type" | "states" | "region_criteria">
) =>
  getRuleRegionCriteria(rule).reduce((highest, criterion) => {
    if (criterion.type === "zip") return Math.max(highest, 4);
    if (criterion.type === "city_state" || criterion.type === "county_state") return Math.max(highest, 3);
    if (criterion.type === "state") return Math.max(highest, 2);
    if (criterion.type === "federal") return Math.max(highest, 1);

    return highest;
  }, 0);

const ruleHasFederalRegion = (rule: Pick<RuntimeRule, "region_type" | "states" | "region_criteria">) =>
  getRuleRegionCriteria(rule).some((criterion) => criterion.type === "federal");

const ruleRequiresDestinationRegion = (rule: Pick<RuntimeRule, "region_type" | "states" | "region_criteria">) =>
  getRuleRegionSpecificity(rule) > 1;

const getRuleStateCriteriaValues = (
  rule: Pick<RuntimeRule, "region_type" | "states" | "region_criteria">
) =>
  getRuleRegionCriteria(rule)
    .filter((criterion) => criterion.type === "state" && criterion.operator === "is")
    .flatMap((criterion) => criterion.values)
    .map((state) => normalizeStateCode(state))
    .filter(Boolean);

const normalizeRegionContext = (
  value: unknown,
  fallbackZip?: string | null,
  fallbackState?: string | null
): RuleRegionContext | null => {
  const region = value && typeof value === "object" ? (value as any) : {};
  const zip = normalizeZip(region.zip || fallbackZip || "");
  const state = normalizeStateCode(region.state || fallbackState || "");
  const city = String(region.city || "").trim();
  const county = String(region.county || "").trim();
  const counties = Array.isArray(region.counties)
    ? region.counties.map((entry: unknown) => String(entry ?? "").trim()).filter(Boolean)
    : [];

  if (!zip && !state && !city && !county && !counties.length) {
    return null;
  }

  return {
    zip: zip || null,
    state: state || null,
    city: city || null,
    county: county || null,
    counties,
  };
};

const getConditionalRegionContext = (conditional: any): RuleRegionContext | null =>
  normalizeRegionContext(
    conditional?.region,
    conditional?.zip || conditional?.postalCode || null,
    conditional?.state || null
  );

const normalizeRuleVariants = (variants: unknown): RuntimeRuleVariant[] => {
  const seen = new Set<string>();

  return (Array.isArray(variants) ? variants : [])
    .map((variant: any) => ({
      product_id: Number(variant?.product_id ?? variant?.productid),
      variant_id: Number(variant?.variant_id ?? variant?.variantid),
    }))
    .filter((variant) => {
      if (
        !Number.isInteger(variant.product_id) ||
        variant.product_id <= 0 ||
        !Number.isInteger(variant.variant_id) ||
        variant.variant_id <= 0
      ) {
        return false;
      }

      const key = `${variant.product_id}:${variant.variant_id}`;
      if (seen.has(key)) {
        return false;
      }

      seen.add(key);
      return true;
    });
};

const normalizeRules = (rules: unknown): RuntimeRule[] =>
  (Array.isArray(rules) ? rules : [])
    .map((rule: any) => ({
      id: Number(rule?.id),
      name: String(rule?.name || ""),
      description: rule?.description ? String(rule.description) : null,
      type: String(rule?.type || ""),
      priority: Number(rule?.priority || 0),
      region_type: String(rule?.region_type || "").toLowerCase(),
      states: Array.isArray(rule?.states)
        ? rule.states.map((state: unknown) => normalizeStateCode(state)).filter(Boolean)
        : [],
      region_match_mode: rule?.region_match_mode === "all" ? ("all" as const) : ("any" as const),
      region_criteria: normalizeRuleRegionCriteria(rule?.region_criteria),
      run_transfer_workflow: Boolean(rule?.run_transfer_workflow),
      identity_verification_config: normalizeIdentityVerificationPolicyConfig(rule?.identity_verification_config),
      is_active: rule?.is_active !== false,
      products: Array.isArray(rule?.products)
        ? rule.products.map((id: unknown) => Number(id)).filter((id: number) => Number.isInteger(id) && id > 0)
        : [],
      variants: normalizeRuleVariants(rule?.variants),
      categories: Array.isArray(rule?.categories)
        ? rule.categories.map((id: unknown) => Number(id)).filter((id: number) => Number.isInteger(id) && id > 0)
        : [],
      custom_fields: Array.isArray(rule?.custom_fields)
        ? rule.custom_fields
            .map((field: any) => ({
              field_name: String(field?.field_name || "").trim(),
              field_value:
                field?.field_value === null || field?.field_value === undefined
                  ? null
                  : String(field.field_value).trim(),
            }))
            .filter((field: any) => field.field_name)
        : [],
      exclusion_products: Array.isArray(rule?.exclusion_products)
        ? rule.exclusion_products.map((id: unknown) => Number(id)).filter((id: number) => Number.isInteger(id) && id > 0)
        : [],
      exclusion_variants: normalizeRuleVariants(rule?.exclusion_variants),
      exclusion_categories: Array.isArray(rule?.exclusion_categories)
        ? rule.exclusion_categories.map((id: unknown) => Number(id)).filter((id: number) => Number.isInteger(id) && id > 0)
        : [],
      exclusion_custom_fields: Array.isArray(rule?.exclusion_custom_fields)
        ? rule.exclusion_custom_fields
            .map((field: any) => ({
              field_name: String(field?.field_name || "").trim(),
              field_value:
                field?.field_value === null || field?.field_value === undefined
                  ? null
                  : String(field.field_value).trim(),
            }))
            .filter((field: any) => field.field_name)
        : [],
      item_type:
        rule?.item_type === null || rule?.item_type === undefined
          ? null
          : String(rule.item_type).trim() || null,
      item_subtype:
        rule?.item_subtype === null || rule?.item_subtype === undefined
          ? null
          : String(rule.item_subtype).trim() || null,
    }))
    .filter((rule) => Number.isInteger(rule.id) && rule.id > 0 && rule.type && rule.is_active);

const productMatchesRuleCriteria = (
  product: any,
  criteria: Pick<RuntimeRule, "products" | "categories" | "custom_fields">
) => {
  const productId = Number(product?.entityId);
  const categoryIds = Array.isArray(product?.categoryIds)
    ? product.categoryIds.map((category: any) => Number(category?.entityId)).filter((id: number) => Number.isInteger(id))
    : [];
  const customFields = Array.isArray(product?.customFields) ? product.customFields : [];

  if (criteria.products.length && criteria.products.includes(productId)) {
    return true;
  }

  if (criteria.categories.length) {
    console.log("[MasterFFL][Rules] category match check", {
      productId: product?.entityId,
      normalizedCategoryIds: categoryIds,
      rawCategoryIds: product?.categoryIds,
      multiChannelCategories: product?.multiChannelCategories,
      ruleCategoryIds: criteria.categories,
      matched: criteria.categories.some((categoryId) => categoryIds.includes(categoryId)),
    });
  }

  if (criteria.categories.length && criteria.categories.some((categoryId) => categoryIds.includes(categoryId))) {
    return true;
  }

  if (
    criteria.custom_fields.length &&
    criteria.custom_fields.some((ruleField) =>
      customFields.some((productField: any) => {
        const nameMatches = normalizeText(productField?.name) === normalizeText(ruleField.field_name);
        if (!nameMatches) {
          return false;
        }

        if (ruleField.field_value === null || ruleField.field_value === undefined || ruleField.field_value === "") {
          return true;
        }

        return normalizeText(productField?.value) === normalizeText(ruleField.field_value);
      })
    )
  ) {
    return true;
  }

  return false;
};

const lineItemProductId = (lineItem: any, product: any) => {
  const productId = Number(lineItem?.productEntityId ?? lineItem?.productId ?? product?.entityId);

  return Number.isInteger(productId) && productId > 0 ? productId : null;
};

const lineItemVariantId = (lineItem: any) => {
  const variantId = Number(lineItem?.variantEntityId ?? lineItem?.variantId);

  return Number.isInteger(variantId) && variantId > 0 ? variantId : null;
};

const lineItemEntityId = (lineItem: any) => {
  const itemId = String(lineItem?.entityId ?? lineItem?.id ?? lineItem?.itemId ?? "").trim();

  return itemId || null;
};

const variantMappingsMatchLineItem = (
  variants: RuntimeRuleVariant[],
  lineItem: any,
  product: any
) => {
  const productId = lineItemProductId(lineItem, product);
  const variantId = lineItemVariantId(lineItem);

  if (!productId || !variantId) {
    return false;
  }

  return variants.some(
    (variant) => variant.product_id === productId && variant.variant_id === variantId
  );
};

const productMappingsMatchLineItem = (
  products: number[],
  lineItem: any,
  product: any
) => {
  const productId = lineItemProductId(lineItem, product);

  return Boolean(productId && products.includes(productId));
};

const productMatchesNonProductCriteria = (
  product: any,
  criteria: Pick<RuntimeRule, "categories" | "custom_fields">
) =>
  productMatchesRuleCriteria(product, {
    products: [],
    categories: criteria.categories,
    custom_fields: criteria.custom_fields,
  });

const getLineItemRuleMatch = (
  rule: RuntimeRule,
  product: any,
  lineItem: any
): RuntimeRuleMatch | null => {
  if (rule.type === "block_checkout") {
    return {
      rule,
      matchSource: "criteria_inclusion",
      excluded: false,
    };
  }

  if (
    rule.type === "route_to_ffl" &&
    variantMappingsMatchLineItem(rule.exclusion_variants, lineItem, product)
  ) {
    return {
      rule,
      matchSource: "variant_exclusion",
      excluded: true,
    };
  }

  if (variantMappingsMatchLineItem(rule.variants, lineItem, product)) {
    return {
      rule,
      matchSource: "variant_inclusion",
      excluded: false,
    };
  }

  const productInclusionMatch = productMappingsMatchLineItem(rule.products, lineItem, product);
  const criteriaInclusionMatch = productMatchesNonProductCriteria(product, {
      categories: rule.categories,
      custom_fields: rule.custom_fields,
  });

  if (!productInclusionMatch && !criteriaInclusionMatch) {
    return null;
  }

  if (rule.type === "route_to_ffl") {
    const productExclusionMatch = productMappingsMatchLineItem(
      rule.exclusion_products,
      lineItem,
      product
    );
    const criteriaExclusionMatch = productMatchesNonProductCriteria(product, {
      categories: rule.exclusion_categories,
      custom_fields: rule.exclusion_custom_fields,
    });

    if (productExclusionMatch || criteriaExclusionMatch) {
      return {
        rule,
        matchSource: productExclusionMatch ? "product_exclusion" : "criteria_exclusion",
        excluded: true,
      };
    }
  }

  if (productInclusionMatch || criteriaInclusionMatch) {
    return {
      rule,
      matchSource: productInclusionMatch ? "product_inclusion" : "criteria_inclusion",
      excluded: false,
    };
  }

  return null;
};

const MATCH_SOURCE_PRIORITY: Record<RuntimeRuleMatchSource, number> = {
  variant_exclusion: 1,
  variant_inclusion: 2,
  product_exclusion: 3,
  product_inclusion: 4,
  criteria_exclusion: 5,
  criteria_inclusion: 6,
};

const getWinningLineItemMatch = (matches: RuntimeRuleMatch[]) => {
  if (!matches.length) {
    return null;
  }

  return matches.reduce((winner, current) => {
    if (!winner) {
      return current;
    }

    const currentSourcePriority = MATCH_SOURCE_PRIORITY[current.matchSource];
    const winnerSourcePriority = MATCH_SOURCE_PRIORITY[winner.matchSource];
    const currentIsVariantMatch = current.matchSource === "variant_exclusion" || current.matchSource === "variant_inclusion";
    const winnerIsVariantMatch = winner.matchSource === "variant_exclusion" || winner.matchSource === "variant_inclusion";

    if (currentIsVariantMatch || winnerIsVariantMatch) {
      if (currentSourcePriority < winnerSourcePriority) {
        return current;
      }

      if (currentSourcePriority > winnerSourcePriority) {
        return winner;
      }
    } else {
      if (current.excluded && !winner.excluded) {
        return current;
      }

      if (!current.excluded && winner.excluded) {
        return winner;
      }
    }

    const currentRegionSpecificity = getRuleRegionSpecificity(current.rule);
    const winnerRegionSpecificity = getRuleRegionSpecificity(winner.rule);

    if (currentRegionSpecificity > winnerRegionSpecificity) {
      return current;
    }

    if (currentRegionSpecificity < winnerRegionSpecificity) {
      return winner;
    }

    if (current.rule.priority < winner.rule.priority) {
      return current;
    }

    if (current.rule.priority === winner.rule.priority && current.rule.id < winner.rule.id) {
      return current;
    }

    return winner;
  }, null as RuntimeRuleMatch | null);
};

const higherPriorityMatch = (left: RuntimeRuleMatch | null, right: RuntimeRuleMatch | null) => {
  if (!left) return right;
  if (!right) return left;

  if (left.rule.priority < right.rule.priority) return left;
  if (left.rule.priority > right.rule.priority) return right;

  return left.rule.id <= right.rule.id ? left : right;
};

const getWinningRule = (rules: RuntimeRule[]) => {
  if (!rules.length) {
    return null;
  }

  return rules.reduce((winner, current) => {
    if (!winner) {
      return current;
    }

    if (current.priority < winner.priority) {
      return current;
    }

    if (current.priority === winner.priority && current.id < winner.id) {
      return current;
    }

    return winner;
  }, null as RuntimeRule | null);
};

const getRuleDisplayLabel = (rule: RuntimeRule) => {
  const trimmedName = String(rule?.name || "").trim();
  if (trimmedName) {
    return trimmedName;
  }

  if (rule.type === "route_to_ffl") return "Direct to Dealer";
  if (rule.type === "block_product_state") return "Restricted Product";
  if (rule.type === "block_checkout") return "State Block";

  return "Restricted Item";
};

const getRuleDescription = (rule: RuntimeRule | null) =>
  rule && typeof rule.description === "string" ? rule.description : "";

const getProductCustomField = (product: any, fieldName: unknown) => {
  const normalizedFieldName = normalizeText(fieldName);

  if (!normalizedFieldName || !Array.isArray(product?.customFields)) {
    return null;
  }

  return (
    product.customFields.find(
      (field: any) => normalizeText(field?.name) === normalizedFieldName
    ) || null
  );
};

const hasLegacyCategoryMappingMatch = (
  product: any,
  mapping: MasterFFLContextType["mappingData"]
) => {
  const categoryIds = Array.isArray(product?.categoryIds)
    ? product.categoryIds
        .map((category: any) => Number(category?.entityId))
        .filter((id: number) => Number.isInteger(id) && id > 0)
    : [];

  const categoryMappings = Array.isArray(mapping?.category_mapping)
    ? mapping.category_mapping
    : [];

  return categoryMappings.some((entry: any) =>
    categoryIds.includes(Number(entry?.categoryId))
  );
};

const isLegacyFflProduct = (
  product: any,
  mapping: MasterFFLContextType["mappingData"]
) => {
  const fflField = getProductCustomField(
    product,
    mapping?.ffl_custom_attribute_name
  );

  if (fflField) {
    return normalizeText(fflField?.value) !== "no";
  }

  return hasLegacyCategoryMappingMatch(product, mapping);
};

const isLegacyNfaProduct = (product: any, mapping: MasterFFLContextType["mappingData"]) => {
  const fflFirearmAttr =
    mapping?.ffl_firearm_custom_attribute_name?.trim()?.toLowerCase() ?? "";
  const fflFirearmValue = mapping?.ffl_firearm_custom_attribute_value ?? "";

  return Array.isArray(product?.customFields) && product.customFields.some(
    (field: any) =>
      normalizeText(field?.name) === fflFirearmAttr &&
      normalizeText(field?.value) === normalizeText(fflFirearmValue?.[3])
  );
};


const init = async () => {
  const [mapping, cart, checkoutSettings] = await Promise.all([
    getMappingData(),
    getCart(),
    getCheckoutSettings(),
  ]);

  let isFFL = false;
  let isSuppressor = false;
  let isEntirelyFFL = false;

  window.masterFFLConfig = window.masterFFLConfig || ({} as MasterFFLBaseConfig);
  window.masterFFLConfig.hasMultiShippingEnabled =
    checkoutSettings.storeConfig.checkoutSettings.hasMultiShippingEnabled;

  fflProducts.clear();
  fflLineItems.clear();
  alwaysFFLProducts.clear();
  conditionalFFLProducts.clear();
  potentialRestrictedProducts.clear();
  potentialRestrictedTypes.clear();

  const conditional = (window as any).masterFFLConditional;
  const currentState = conditional?.state ? normalizeStateCode(conditional.state) : null;
  const currentRegionContext = getConditionalRegionContext(conditional);
  const identityVerificationEnabled = isIdentityVerificationFeatureEnabled(
    mapping?.identityVerificationEnabled
  );
  const rules = normalizeRules((mapping as any)?.rules);

  console.log("[MasterFFL][Rules] state debug", {
    raw: conditional?.state ?? null,
    normalized: normalizeStateCode(conditional?.state),
    regionContext: currentRegionContext,
  });

  console.log("[MasterFFL][Rules] init context", {
    storeHash: getConfig().storeHash || null,
    currentState,
    currentRegionContext,
    identityVerificationEnabled,
    totalRulesReceived: Array.isArray((mapping as any)?.rules) ? (mapping as any).rules.length : 0,
    activeRulesNormalized: rules.map((rule) => ({
      id: rule.id,
      name: rule.name,
      type: rule.type,
      priority: rule.priority,
      region_type: rule.region_type,
      states: rule.states,
      region_match_mode: rule.region_match_mode,
      region_criteria: rule.region_criteria,
      products: rule.products,
      categories: rule.categories,
      custom_fields: rule.custom_fields,
      identity_verification_config: rule.identity_verification_config,
    })),
  });

  const productIds = cart?.lineItems.physicalItems.map(
    (item: any) => item.productEntityId
  ) || [];
  const products = await SDK.getProducts(productIds);
  const productById = new Map<number, any>(
    products.map((product: any) => [Number(product?.entityId), product])
  );
  const cartLineItems = Array.isArray(cart?.lineItems?.physicalItems)
    ? cart.lineItems.physicalItems
    : [];
  totalProductsInCart = products.length;
  const derivedRestrictedTypes = new Set<string>();
  const blockedProductIds = new Set<number>();
  const potentialStateBlockProducts = new Map<number, string>();
  const matchedDirectToDealerRules = new Map<number, MatchedIdentityClassification>();
  let matchedBlockAllRule: RuntimeRule | null = null;
  let matchedBlockedProductRule: RuntimeRule | null = null;

  cartLineItems.forEach((lineItem: any) => {
    const productId = Number(lineItem?.productEntityId);
    const product = productById.get(productId);

    if (!product) {
      return;
    }

    const allLineItemMatches = rules
      .filter((rule) => rule.type !== "block_checkout" && rule.type !== "identity_verification")
      .map((rule) => getLineItemRuleMatch(rule, product, lineItem))
      .filter((match: RuntimeRuleMatch | null): match is RuntimeRuleMatch => Boolean(match));

    const destinationDependentMatchingRules = allLineItemMatches
      .filter((match) => !match.excluded && ruleRequiresDestinationRegion(match.rule))
      .map((match) => match.rule);

    destinationDependentMatchingRules.forEach((potentialRule) => {
      const label = getRuleDisplayLabel(potentialRule);

      potentialRestrictedProducts.set(product.entityId, label);
      potentialRestrictedTypes.add(label);

      if (potentialRule.type === "block_product_state") {
        potentialStateBlockProducts.set(product.entityId, label);
      }
    });

    const activeLineItemMatchesForRegion = allLineItemMatches.filter((match) =>
      ruleAppliesToRegionContext(match.rule, currentRegionContext)
    );

    const winningMatchBySpecificity = getWinningLineItemMatch(activeLineItemMatchesForRegion);
    const winningBlockMatch = getWinningLineItemMatch(
      activeLineItemMatchesForRegion.filter((match) => match.rule.type === "block_product_state")
    );
    const winningMatch =
      winningBlockMatch && winningMatchBySpecificity?.rule.type !== "block_product_state"
        ? higherPriorityMatch(winningBlockMatch, winningMatchBySpecificity)
        : winningMatchBySpecificity;
    const winningRule = winningMatch?.excluded ? null : winningMatch?.rule || null;
    const legacyFflMatch = !winningMatch?.excluded && isLegacyFflProduct(product, mapping);

    if (legacyFflMatch) {
      fflProducts.set(product.entityId, true);
      const itemId = lineItemEntityId(lineItem);
      if (itemId) {
        fflLineItems.set(itemId, lineItem);
      }
      alwaysFFLProducts.set(product.entityId, true);
    }

    if (!winningMatch?.excluded && isLegacyNfaProduct(product, mapping)) {
      isSuppressor = true;
    }

    console.log("[MasterFFL][Rules] product evaluation", {
      productId: product.entityId,
      lineItemId: lineItem.entityId,
      variantId: lineItem.variantEntityId ?? null,
      categoryIds: Array.isArray(product?.categoryIds)
        ? product.categoryIds.map((category: any) => category?.entityId)
        : [],
      multiChannelCategories: Array.isArray(product?.multiChannelCategories)
        ? product.multiChannelCategories
        : [],
      customFields: Array.isArray(product?.customFields)
        ? product.customFields.map((field: any) => ({
            name: field?.name,
            value: field?.value,
          }))
        : [],
      currentState,
      currentRegionContext,
      matchedRuleIds: allLineItemMatches.map((match) => match.rule.id),
      activeRuleIdsForRegion: activeLineItemMatchesForRegion.map((match) => match.rule.id),
      winningMatchSource: winningMatch?.matchSource || null,
      excludedByRule: winningMatch?.excluded ? winningMatch.rule.id : null,
      winningRule: winningRule
        ? {
            id: winningRule.id,
            name: winningRule.name,
            type: winningRule.type,
            priority: winningRule.priority,
            states: winningRule.states,
            region_match_mode: winningRule.region_match_mode,
            region_criteria: winningRule.region_criteria,
          }
        : null,
    });

    if (!winningRule) {
      return;
    }

    const label = getRuleDisplayLabel(winningRule);
    derivedRestrictedTypes.add(label);

    if (winningRule.type === "route_to_ffl") {
      fflProducts.set(product.entityId, true);
      const itemId = lineItemEntityId(lineItem);
      if (itemId) {
        fflLineItems.set(itemId, lineItem);
      }

      if (ruleHasFederalRegion(winningRule)) {
        alwaysFFLProducts.set(product.entityId, true);
      } else {
        conditionalFFLProducts.set(product.entityId, true);
      }

      const matchedRule = matchedDirectToDealerRules.get(winningRule.id) || {
        productIds: new Set<number>(),
        lineItemIds: new Set<string>(),
      };
      matchedRule.productIds.add(Number(product.entityId));
      if (itemId) {
        matchedRule.lineItemIds.add(itemId);
      }
      matchedDirectToDealerRules.set(winningRule.id, matchedRule);

      if (
        normalizeTypeLabel(winningRule.item_type) === "nfa" ||
        isLegacyNfaProduct(product, mapping)
      ) {
        isSuppressor = true;
      }
    }

    if (winningRule.type === "block_product_state") {
      blockedProductIds.add(Number(product.entityId));

      if (
        !matchedBlockedProductRule ||
        winningRule.priority < matchedBlockedProductRule.priority ||
        (winningRule.priority === matchedBlockedProductRule.priority &&
          winningRule.id < matchedBlockedProductRule.id)
      ) {
        matchedBlockedProductRule = winningRule;
      }
    }

  });

  const governmentIdVerificationRequirements = resolveIdentityVerificationRequirements(
    rules,
    matchedDirectToDealerRules,
    currentRegionContext?.state,
    identityVerificationEnabled
  );

  matchedBlockAllRule = getWinningRule(
    rules.filter((rule) => rule.type === "block_checkout" && ruleAppliesToRegionContext(rule, currentRegionContext))
  );

  const hasPotentialStateBlock =
    potentialStateBlockProducts.size > 0 ||
    (!currentRegionContext && rules.some((rule) => rule.type === "block_checkout" && ruleRequiresDestinationRegion(rule)));

  console.log("[MasterFFL][Rules] block checkout evaluation", {
    currentState,
    currentRegionContext,
    blockCheckoutRuleIdsForRegion: rules
      .filter((rule) => rule.type === "block_checkout" && ruleAppliesToRegionContext(rule, currentRegionContext))
      .map((rule) => ({
        id: rule.id,
        name: rule.name,
        priority: rule.priority,
        states: rule.states,
        region_match_mode: rule.region_match_mode,
        region_criteria: rule.region_criteria,
      })),
    matchedBlockAllRule: matchedBlockAllRule
      ? {
          id: matchedBlockAllRule.id,
          name: matchedBlockAllRule.name,
          priority: matchedBlockAllRule.priority,
          states: matchedBlockAllRule.states,
          region_match_mode: matchedBlockAllRule.region_match_mode,
          region_criteria: matchedBlockAllRule.region_criteria,
          description: matchedBlockAllRule.description,
        }
      : null,
    blockedProductIds: [...blockedProductIds],
  });

  (window as any).masterFFLPotential = {
    hasPotentialRestrictions: potentialRestrictedProducts.size > 0,
    types: [...potentialRestrictedTypes],
  };

  const blockedPickupStates = [...new Set(
    rules
      .filter(
        (rule) =>
          getRuleStateCriteriaValues(rule).length > 0 &&
          (rule.type === "block_checkout" || rule.type === "block_product_state")
      )
      .flatMap((rule) => getRuleStateCriteriaValues(rule))
      .filter((stateCode) => {
        if (
          rules.some(
            (rule) =>
              rule.type === "block_checkout" &&
              ruleAppliesToRegionContext(rule, { state: stateCode })
          )
        ) {
          return true;
        }

        return cartLineItems.some((lineItem: any) => {
          const productId = Number(lineItem?.productEntityId);
          const product = productById.get(productId);

          if (!product) {
            return false;
          }

          const activeLineItemMatchesForState = rules
            .filter((rule) => rule.type !== "block_checkout" && rule.type !== "identity_verification")
            .map((rule) => getLineItemRuleMatch(rule, product, lineItem))
            .filter((match: RuntimeRuleMatch | null): match is RuntimeRuleMatch => Boolean(match))
            .filter((match) => ruleAppliesToRegionContext(match.rule, { state: stateCode }));

          const winningMatchBySpecificity = getWinningLineItemMatch(activeLineItemMatchesForState);
          const winningBlockMatch = getWinningLineItemMatch(
            activeLineItemMatchesForState.filter((match) => match.rule.type === "block_product_state")
          );
          const winningMatch =
            winningBlockMatch && winningMatchBySpecificity?.rule.type !== "block_product_state"
              ? higherPriorityMatch(winningBlockMatch, winningMatchBySpecificity)
              : winningMatchBySpecificity;
          const winningRule = winningMatch?.excluded ? null : winningMatch?.rule || null;

          return winningRule?.type === "block_product_state";
        });
      })
  )].sort();

  /*
   * ---------------------------------------------------------
   * 5️. Final flags
   * ---------------------------------------------------------
   */
  
  const hasGlobalBlock = Boolean(matchedBlockAllRule);

  console.log("HASGLOBALBLOCK: ", hasGlobalBlock);

  isFFL = fflLineItems.size > 0 || hasGlobalBlock;
  
  isEntirelyFFL =
    cartLineItems.length > 0 && cartLineItems.length === fflLineItems.size;

  const hasAlwaysFFL = alwaysFFLProducts.size > 0;
  const hasConditionalFFL = conditionalFFLProducts.size > 0;
  const isStateRestrictedOnly = hasConditionalFFL && !hasAlwaysFFL && !isSuppressor;
  const hardBlockMessage = getRuleDescription(matchedBlockAllRule) || getRuleDescription(matchedBlockedProductRule);
  const requiresGovernmentIdVerification = governmentIdVerificationRequirements.length > 0;

  const fflState = {
    isFFL,
    fflLineItems,
    isSuppressor,
    isEntirelyFFL,
    hasFederalFFLItems: hasAlwaysFFL,
    isStateRestrictedOnly,
    potentialRestrictedProducts,
    hasPotentialStateBlock,
    conditionalFFLProducts,
    potentialRestrictedTypes: [...potentialRestrictedTypes],
    restrictedTypesInCart: [...derivedRestrictedTypes],
    identityVerificationEnabled,
    requiresGovernmentIdVerification,
    governmentIdVerificationRequirements,
  };

  (window as any).masterFFLRuleEvaluation = {
    state: currentState,
    region: currentRegionContext,
    blockedPickupStates,
    matchedBlockAllRuleId: matchedBlockAllRule?.id || null,
    hardBlocked: Boolean(matchedBlockAllRule) || blockedProductIds.size > 0,
    blockedProductIds: [...blockedProductIds],
    hardBlockMessage,
    directToDealerRequired: isFFL,
    directToDealerRestrictedKeys: [...derivedRestrictedTypes],
    identityVerificationEnabled,
    requiresGovernmentIdVerification,
    governmentIdVerificationRequirements,
  };

  console.log("[MasterFFL][IDV] shipping rule evaluation", {
    storeHash: getConfig().storeHash || null,
    checkoutId: getConfig().checkoutId || null,
    state: currentState,
    region: currentRegionContext,
    identityVerificationEnabled,
    requiresGovernmentIdVerification,
    governmentIdVerificationRequirements,
  });

  (window as any).masterFFLState = fflState;

  return fflState;
};

