const applyIdentityVerificationGateToMapping = (
  value: unknown
): NonNullable<MasterFFLContextType["mappingData"]> => {
  const rawMapping = value && typeof value === "object"
    ? value as NonNullable<MasterFFLContextType["mappingData"]>
    : {} as NonNullable<MasterFFLContextType["mappingData"]>;
  const identityVerificationEnabled = isIdentityVerificationFeatureEnabled(
    rawMapping.identityVerificationEnabled
  );

  return {
    ...rawMapping,
    identityVerificationEnabled,
    rules: identityVerificationEnabled
      ? rawMapping.rules
      : rawMapping.rules?.filter((rule) => rule?.type !== "identity_verification"),
  };
};

const publishIdentityVerificationGate = (
  mapping: NonNullable<MasterFFLContextType["mappingData"]>
) => {
  (window as any).masterFFLIdentityVerificationEnabled =
    isIdentityVerificationFeatureEnabled(mapping.identityVerificationEnabled);
};

const getMappingData = async () => {
  if (!getConfig().storeHash) {
    console.warn("[MasterFFL] getMappingData called without storeHash");
  }

  // return cached mapping if it exists
  const cacheKey = `mapping-${getConfig().storefrontApiToken}-${getConfig().storeHash || "unknown-store"}`;
  window.masterFFLCache = window.masterFFLCache || {};
  const cachedMapping = window.masterFFLCache[cacheKey];

  if (cachedMapping && Object.keys(cachedMapping).length > 0) {
    const mapping = applyIdentityVerificationGateToMapping(cachedMapping);

    window.masterFFLCache[cacheKey] = mapping;
    publishIdentityVerificationGate(mapping);

    return mapping;
  }

  // get the mapping from the API

  const response = await fetch(`${getConfig().appUrl}/api/internal/mappingdata`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      storeHash: getConfig().storeHash ?? "",
    }),
  });

  const data = await response.json();
  const mapping = applyIdentityVerificationGateToMapping(data);
  const identityVerificationEnabled = mapping.identityVerificationEnabled === true;

  publishIdentityVerificationGate(mapping);

  console.log("[MasterFFL][Rules] mapping payload received", {
    storeHash: getConfig().storeHash || null,
    identityVerificationEnabled,
    hasRules: Array.isArray((mapping as any)?.rules),
    ruleCount: Array.isArray((mapping as any)?.rules) ? (mapping as any).rules.length : 0,
    rules: Array.isArray((mapping as any)?.rules)
      ? (mapping as any).rules.map((rule: any) => ({
          id: rule?.id,
          name: rule?.name,
          type: rule?.type,
          priority: rule?.priority,
          region_type: rule?.region_type,
          states: rule?.states,
          region_match_mode: rule?.region_match_mode,
          region_criteria: rule?.region_criteria,
        }))
      : [],
  });

  // cache the mapping
  window.masterFFLCache[cacheKey] = mapping;

  // return the mapping
  return mapping;
};

const getCheckoutSettings = async () => {
  // return cached cart if it exists
  const cacheKey = `checkout-settings-${getConfig().storefrontApiToken}`;
  window.masterFFLCache = window.masterFFLCache || {};
  const cachedCart = window.masterFFLCache[cacheKey];
  if (cachedCart) {
    return cachedCart;
  }

  const response = await fetch(`/api/storefront/checkout-settings?checkoutId=${getConfig().checkoutId}`, {
    method: "GET",
    headers: { "Content-Type": "application/json", "x-api-internal": "This API endpoint is for internal use only and may change in the future" },
  });
  const data = await response.json();
  const checkoutSettings = data as any;

  // cache the checkout settings
  window.masterFFLCache[cacheKey] = checkoutSettings;

  return checkoutSettings;
};

