import type { CheckoutService } from "@bigcommerce/checkout-sdk";
import type { CheckoutRuleFeeMethod } from "../../types";

type RefreshRuleFeesOptions = {
  appUrl: string;
  storeHash?: string;
  checkoutId?: string;
  checkoutService: CheckoutService;
  state?: string | null;
  checkoutMethod?: CheckoutRuleFeeMethod | null;
};

const CHECKOUT_INCLUDE = {
  params: { include: { "consignments.availableShippingOptions": true } },
};

export async function refreshRuleFees({
  appUrl,
  storeHash,
  checkoutId,
  checkoutService,
  state,
  checkoutMethod,
}: RefreshRuleFeesOptions) {
  if (!appUrl || !storeHash || !checkoutId) return;

  const response = await fetch(`${appUrl}/api/internal/rules/fee`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "ngrok-skip-browser-warning": "true",
    },
    body: JSON.stringify({
      storeHash,
      checkoutId,
      state: state || undefined,
      checkoutMethod: checkoutMethod || undefined,
    }),
  });

  if (!response.ok) {
    const payload = await response.json().catch(() => null);
    throw new Error(payload?.error || "Failed to refresh rule fees");
  }

  await checkoutService.loadCheckout(checkoutId, CHECKOUT_INCLUDE);
}

export async function clearRuleFees({
  appUrl,
  storeHash,
  checkoutId,
}: Pick<RefreshRuleFeesOptions, "appUrl" | "storeHash" | "checkoutId">) {
  if (!appUrl || !storeHash || !checkoutId) return;

  const response = await fetch(`${appUrl}/api/internal/rules/fee`, {
    method: "DELETE",
    headers: {
      "Content-Type": "application/json",
      "ngrok-skip-browser-warning": "true",
    },
    body: JSON.stringify({ storeHash, checkoutId }),
  });

  if (!response.ok) {
    const payload = await response.json().catch(() => null);
    throw new Error(payload?.error || "Failed to clear rule fees");
  }
}
