  const handleSubmit = async (e: React.MouseEvent<HTMLButtonElement> | React.KeyboardEvent<HTMLInputElement>) => {
    e.preventDefault();
    
    setErrors({ postalCode: "", acceptTerms: "", fflId: "" });

    if (!values.postalCode) {
      setErrors({ ...errors, postalCode: `${config.lang.postalCodeLabel} is required` });

      return;
    }

    const zip = (values.postalCode || "").replace(/\D/g, "").slice(0, 5);

    setValues({ ...values, postalCode: zip });
    sessionStorage.setItem(`${config.checkoutId}-postalCode`, zip);
    
    // re-run ZIP restriction logic + reclassify before opening dealer modal
    const nextIsFFL = await runZipRestrictionCheck(zip, true);
    const restrictionResult = (window as any).masterFFLCheckoutRestrictionResult;
    const identityVerificationPending =
      isIdentityVerificationFeatureEnabled(
        (window as any).masterFFLIdentityVerificationEnabled
      ) &&
      hasPendingIdentityVerification(
        Boolean(restrictionResult?.requiresGovernmentIdVerification),
        restrictionResult?.governmentIdVerificationRequirements,
        (window as any).masterFFLIdentityVerifications
      );
    
    if (nextIsFFL) {
      if (identityVerificationPending) {
        setIsModalOpen(false);

        return;
      }

      setIsModalOpen(true);
    } else if (restrictionResult?.hardBlocked) {
      // Provider already sets the user-facing error message for hard blocks.
      return;
    } else {
      setIsModalOpen(false);
      setSelectedDealer(null);
      setIsFFL(false);
      setShippingLocked(false);
      await handleCleanup();
      SDK.removeSession(config.checkoutId, "selectedDealer");
      sessionStorage.removeItem(`${config.checkoutId}-fulfillmentMode`);
      sessionStorage.setItem(`${config.checkoutId}-postalCode`, zip);
      sessionStorage.setItem("masterFFL_fflZip", zip);
      setValues({ ...values, postalCode: zip });
      await checkoutService.loadCheckout(config.checkoutId, {
        params: { include: { "consignments.availableShippingOptions": true } },
      });
    }
    
  };

