  const formatDirectAddress = (address?: DealerAddress): string => {
    if (!address) return "";
    return [address.street, address.city, address.state, address.zipCode].filter(Boolean).join(", ");
  };

  const areDealerAddressesEqual = (left?: DealerAddress, right?: DealerAddress): boolean => {
    if (!left || !right) return false;

    const normalize = (value?: string) => (value || "").trim().toUpperCase();
    return (
      normalize(left.street) === normalize(right.street) &&
      normalize(left.city) === normalize(right.city) &&
      normalize(left.state) === normalize(right.state) &&
      normalize(left.zipCode) === normalize(right.zipCode)
    );
  };

