  const saveDirectFflB2bValue = async (value: "premise" | "mailing") => {
    await SDK.saveCheckoutMetadata({ "FFL-isB2B": value });

    const customFieldInputs = document.querySelectorAll<HTMLInputElement>(
      'input[name^="shippingAddress.customFields.field_"]'
    );

    customFieldInputs.forEach((input) => {
      const fieldContainer = input.closest(".form-field");
      const labelText = fieldContainer?.querySelector("label")?.textContent?.toLowerCase() || "";
      if (!labelText.includes("ffl-isb2b")) return;

      const valueSetter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")?.set;
      valueSetter ? valueSetter.call(input, value) : (input.value = value);
      input.dispatchEvent(new Event("input", { bubbles: true }));
      input.dispatchEvent(new Event("change", { bubbles: true }));
    });
  };

  const handleDirectAddressChange = async (addressType: "premiseAddress" | "mailingAddress", address?: DealerAddress) => {
    if (!address) return;
    if (directAddressApplyRef.current) return;

    directAddressApplyRef.current = true;

    try {
      const directZip = (address.zipCode || "").replace(/\D/g, "").slice(0, 5);
      if (directZip) {
        await runZipRestrictionCheck(directZip, true);
        const restrictionResult = (window as any).masterFFLCheckoutRestrictionResult;

        if (restrictionResult?.hardBlocked) {
          return;
        }
      }

      const directSelectedDealer = toDirectSelectedDealer(address);
      const dealerAddress: DealerAddress = {
        id: directDealerShortId,
        name: directDealerRecord?.tradeName || "",
        state: address.state,
        zipCode: address.zipCode,
        street: address.street,
        city: address.city,
      };

      setSelectedDirectAddress(addressType);
      setSelectedDealer(directSelectedDealer);
      SDK.setSession(config.checkoutId, { selectedDealer: JSON.stringify(directSelectedDealer) });
      const { shippingData } = await SDK.saveDealer(config.checkoutId, undefined, dealerAddress);
      setSelectedDealer(directSelectedDealer);
      SDK.setSession(config.checkoutId, { selectedDealer: JSON.stringify(directSelectedDealer) });
      const nextAddress = shippingData?.address || {};

      // Match the existing modal flow: update shippingAddress.* fields so checkout-js
      // recalculates available shipping options for the created consignment.
      Object.keys(nextAddress).forEach((key) => {
        const input = document.querySelector(`[name="shippingAddress.${key}"]`) as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement | null;
        const addressLine1Input =
          key === "address1" ? (document.getElementById("addressLine1Input") as HTMLInputElement | null) : null;
        const nextValue = String(nextAddress[key as keyof typeof nextAddress] ?? "");

        if (input) {
          setFormControlValue(input, nextValue);
        }

        if (addressLine1Input) {
          setFormControlValue(addressLine1Input, nextValue);
        }
      });

      await saveDirectFflB2bValue(addressType === "premiseAddress" ? "premise" : "mailing");
      await refreshCheckoutRuleFees((window as any).masterFFLConditional?.state || address.state || null, "b2b");

    } catch (saveError) {
      console.error("[MasterFFL][DirectFFL] saveDealer failed", saveError);
    } finally {
      directAddressApplyRef.current = false;
    }
  };

